        "story": {
          "setup": "浙江一家做冲压五金件的小厂，三十来号人，前些年给大厂做代工，一个件赚几毛钱，账期三个月，年底一算钱都在别人账上。",
          "conflict": "小单为什么没人接？换一次模具要40分钟到两三小时，机器停着、人等着、电费照付，100件的单摊下来单件成本比大批量高两三倍；一个急单插进来，整条线节奏全乱。",
          "turn": "这家厂第一步没买设备，先改接单逻辑：500件以上走常规线、50到500件走柔性线、50件以下只接老客户；再把换型工时、调试损耗、模具摊销折进报价模型，把换型时间从3小时压到35分钟。三年下来，小批量订单做到四成。",
          "open": "另一家厂的老板更直接：专接一百件以下的非标急单，单价高三成、现款现货不压账，第一年占营收两成，第二年就到了六成。他说，不是活变好了，是不跟他们抢那碗饭了。"
        },
