            "text": "CAR-T这三个字母第一次出现在基本医保里——此前它跟着的说法是：一针上百万。CAR-T的做法不复杂：把人体内的免疫细胞取出来，改成能识别癌细胞的样式，扩增后一针打回去。医生讲完方案，最难听的是那个数字。记住的往往不是原理，是价格。"
