        "cover": "10人作坊 / 论斤卖改论枚 / 年产值2亿",
        "script": [
          {
            "t": "0-9秒",
            "label": "钩子",
            "text": "同样是鱼钩，别人论斤卖，他偏要论枚卖——就这一个改法，把10个人的小作坊做成了年产值2亿。"
          },
          {
            "t": "9-30秒",
            "label": "铺垫",
            "text": "24岁的占志波辞掉了教师的铁饭碗。他要靠一枚小小的鱼钩，撑起一整个厂。这间鱼钩作坊是父亲传下来的。鱼钩论斤卖，最熟练的工人一天只能做3万枚，利润薄得像刀片。占志波每天醒来第一个问题是：怎么活下去。那年他刚辞掉教职，父亲没拦他。"
          },
          {
            "t": "30-46秒",
            "label": "冲突",
            "text": "转机来自一次国际渔具展。他被展台上外国产品的标价牌震住了：同样一枚鱼钩，人家按枚标价、包装考究，自家只能论斤甩卖。订单来了，产能却跟不上，最熟练的工人一天也就3万枚。"
          },
          {
            "t": "46-65秒",
            "label": "反转",
            "text": "他看中一台日本淘汰的鱼钩成型机，用掉全部30万积蓄、再借贷十几万买下。机器运回鄱阳就三天两头出毛病，眼看积蓄要打水漂。没学过一天机械的他，带着几位师傅扎进车间，夜里看书学机械。三个月后，机器转起来了。"
          },
          {
            "t": "65-85秒",
            "label": "细节",
            "text": "接下来几年，他组建研发团队，做出适配各类鱼钩的标准化成型机，日本、欧美的代工单接了一茬又一茬。可占志波心里一直不踏实——代工做得再好，定价权是别人的。他决定启动自主品牌BKK，从论斤卖改成论枚卖，单枚卖到十几元。"
          },
          {
            "t": "85-101秒",
            "label": "结果",
            "text": "今天，这家企业年产鱼钩近30亿枚、年产值超2亿元，BKK商标在全球65个国家注册，拿到49项全球专利，是全球第三大鱼钩生产企业之一。一条从湖边出发的小路，走到了65个国家。"
          },
          {
            "t": "101-120秒",
            "label": "收尾",
            "text": "鄱阳湖边那个只有10个人的作坊里，如今是机器声压过了湖风。2001年那个辞掉教书的24岁年轻人大概没想过，自家做的鱼钩有一天会论枚卖，还挂上自己的牌子。这中间靠的不是运气，是一台旧机器和几年没停过的手艺。"
          }
        ],
