            "text": "10月29日18点多，湖北阳新县一家超市的货架下，躺着一万元现金。员工巡货架时发现了它。钱在地上，人却已经走了。钱被当场清点、封存，随后就报了警。店里的人说了一句很朴素的话：丢钱的人肯定急坏了。那时候天已经黑透了，店里快打烊，一叠现金捡起来，谁也没想着自己留下。"
