            "text": "别人一遍会，他练一百遍。小吴因为早产缺氧患上脑瘫，肢体协调差、口齿不清。小时候他爱看李小龙，初中拿到一根海绵双截棍，对着电视自学，一练就是十余年。家里起初是担心，怕他伤着自己。2009年，他领到二级残疾人证。"
