            "text": "制服留在岸上，人已经下去了。老人被托住、被往岸边带，直到两只手把他拉上岸。剩下的事才发生：有人喊人，有人递毛巾，有人打电话。一件本来只需要一个人做的事，在那几秒里被很多人接住了。从跳下去到把人拉上来，其实并没有多少时间。"
